/**
 * Pipedrive Node - Version 2
 * Discriminator: resource=file, operation=create
 */


interface Credentials {
  pipedriveApi: CredentialReference;
  pipedriveOAuth2Api: CredentialReference;
}

/** Create an activity */
export type PipedriveV2FileCreateParams = {
  resource: 'file';
  operation: 'create';
  authentication?: 'apiToken' | 'oAuth2' | Expression<string>;
/**
 * Input Binary Field
 * @hint The name of the input binary field containing the file to be written
 * @default data
 */
    binaryPropertyName?: string | Expression<string> | PlaceholderValue;
/**
 * Additional Fields
 * @default {}
 */
    additionalFields?: {
    /** ID of the activity this file will be associated with
     * @default 0
     */
    activity_id?: number | Expression<number>;
    /** ID of the deal this file will be associated with
     * @default 0
     */
    deal_id?: number | Expression<number>;
    /** ID of the lead this file will be associated with
     */
    lead_id?: string | Expression<string> | PlaceholderValue;
    /** ID of the organization this file will be associated with. Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;.
     * @loadOptionsMethod getOrganizationIds
     */
    org_id?: string | Expression<string>;
    /** ID of the person this file will be associated with
     * @default 0
     */
    person_id?: number | Expression<number>;
    /** ID of the product this file will be associated with
     * @default 0
     */
    product_id?: number | Expression<number>;
  };
};

export type PipedriveV2FileCreateNode = {
  type: 'n8n-nodes-base.pipedrive';
  version: 2;
  credentials?: Credentials;
  config: NodeConfig<PipedriveV2FileCreateParams>;
};